def choose_move(observation):
    def sget(obj, key, default=None):
        if hasattr(obj, "get"):
            try:
                return obj.get(key, default)
            except Exception:
                return default
        return default

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def step_toward(a, b):
        dx = 0 if b[0] == a[0] else (1 if b[0] > a[0] else -1)
        dy = 0 if b[1] == a[1] else (1 if b[1] > a[1] else -1)
        return [dx, dy]

    def step_away(a, b):
        dx = 0 if b[0] == a[0] else (-1 if b[0] > a[0] else 1)
        dy = 0 if b[1] == a[1] else (-1 if b[1] > a[1] else 1)
        return [dx, dy]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    sx, sy = pos(sget(observation, "self_position", (0, 0)))
    ox, oy = pos(sget(observation, "opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    env = sget(observation, "environment_name", "resource_collection")

    if env == "pursuit_evasion":
        role = sget(observation, "self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = sget(observation, "grid_width", 0)
        h = sget(observation, "grid_height", 0)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan(c, opp_pos)
            if d > best:
                best = d
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = sget(observation, "unclaimed_cells", None)
        if not targets:
            targets = sget(observation, "opponent_territory", None)
        if not targets:
            targets = sget(observation, "border_cells", None)
        if targets:
            best = None
            best_d = None
            for t in targets:
                tp = pos(t, self_pos)
                d = manhattan(self_pos, tp)
                if best is None or d < best_d:
                    best = tp
                    best_d = d
            if best is not None:
                return step_toward(self_pos, best)
        return step_toward(self_pos, opp_pos)

    resources = sget(observation, "resources", None)
    if not resources:
        resources = sget(observation, "resource_positions", None)
    if resources:
        best = None
        best_d = None
        for r in resources:
            rp = pos(r, self_pos)
            d = manhattan(self_pos, rp)
            if best is None or d < best_d:
                best = rp
                best_d = d
        if best is not None:
            return step_toward(self_pos, best)

    return step_away(self_pos, opp_pos)

